<?php
$config=require dirname(__DIR__)."/config.php";require dirname(__DIR__)."/lib/events.php";$events=load_events($config);$token=null;
if($_SERVER["REQUEST_METHOD"]==="POST"){
 $a=$_POST["action"]??"";$id=$_POST["id"]??"";
 if($a==="create"){$name=trim($_POST["name"]??"");$id=trim(strtolower(preg_replace("/[^a-zA-Z0-9]+/","-",$name)),"-");if($id&&$name){$base=$id;$n=2;while(isset($events[$id]))$id=$base."-".$n++;$token=new_upload_token();$events[$id]=["id"=>$id,"name"=>$name,"visibility"=>($_POST["visibility"]??"private")==="public"?"public":"private","active"=>true,"token_hash"=>token_hash($token),"created_at"=>date(DATE_ATOM),"last_upload"=>null,"upload_count"=>0];save_events($config,$events);}}
 if($a==="regen"&&isset($events[$id])){$token=new_upload_token();$events[$id]["token_hash"]=token_hash($token);save_events($config,$events);}
 if($a==="visibility"&&isset($events[$id])){$events[$id]["visibility"]=$events[$id]["visibility"]==="public"?"private":"public";save_events($config,$events);}
}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Event — FOTOGRAFER</title><link rel="stylesheet" href="../assets/app.css"></head><body><header class="sitebar"><div class="brand">FOTOGRAFER<small>OPERATOR</small></div><span class="count"><?=count($events)?> EVENT</span></header><main class="wrap"><div class="topline"><div><div class="eyebrow">Workspace</div><h1>Event & Folder</h1><p>Buat tujuan upload, atur akses galeri, dan kelola token tablet.</p></div></div><?php if($token):?><section class="token"><div class="eyebrow">Token baru — copy sekarang</div><code><?=htmlspecialchars($token)?></code><p>Token asli tidak disimpan. Regenerate bila token hilang atau bocor.</p></section><?php endif?><form class="create panel" method="post"><input type="hidden" name="action" value="create"><input name="name" required placeholder="Nama event, mis. Wedding Andi"><select name="visibility"><option value="private">Private</option><option value="public">Public</option></select><button>Buat event</button></form><div class="events"><?php foreach(array_reverse($events,true) as $e):?><article class="event"><div class="event-head"><div><h2><?=htmlspecialchars($e["name"])?></h2><p class="meta">/<?=htmlspecialchars($e["id"])?> · <?=intval($e["upload_count"]??0)?> foto</p></div><span class="badge <?=($e["visibility"]??"private")==="private"?"private":""?>"><?=strtoupper(htmlspecialchars($e["visibility"]??"private"))?></span></div><p class="meta">Upload terakhir: <?=htmlspecialchars($e["last_upload"]??"Belum ada")?></p><div class="actions"><form method="post"><input type="hidden" name="action" value="visibility"><input type="hidden" name="id" value="<?=htmlspecialchars($e["id"])?>"><button class="secondary">Ubah akses</button></form><form method="post"><input type="hidden" name="action" value="regen"><input type="hidden" name="id" value="<?=htmlspecialchars($e["id"])?>"><button>Token baru</button></form><?php if(($e["visibility"]??"private")==="public"):?><a href="../?event=<?=urlencode($e["id"])?>" target="_blank"><button type="button" class="secondary">Buka galeri</button></a><?php endif?></div></article><?php endforeach?></div></main></body></html>